<script lang="ts">
  import { navigate } from 'svelte-routing'
  import { Minus, Plus, Trash2 } from '@lucide/svelte'
  import { getCart, getProducts, saveCart } from '../data/store'
  import type { CartItem, Product } from '../types'
  let cart = $state<CartItem[]>([]); let products = $state<Product[]>([]); let coupon = $state(''); let applied = $state(false)
  let lines = $derived(cart.map((item) => ({ ...item, product: products.find((product) => product.id === item.productId) })).filter((line) => line.product))
  let subtotal = $derived(lines.reduce((sum, line) => sum + line.product!.price * line.quantity, 0)); let discount = $derived(applied ? subtotal * 0.1 : 0); let shipping = $derived(subtotal > 75 ? 0 : 8); let total = $derived(subtotal - discount + shipping)
  $effect(() => { Promise.all([getCart(), getProducts()]).then(([savedCart, savedProducts]) => { cart = savedCart; products = savedProducts }) })
  async function update(productId: string, color: string, quantity: number): Promise<void> { cart = cart.map((item) => item.productId === productId && item.color === color ? { ...item, quantity } : item).filter((item) => item.quantity > 0); await saveCart(cart) }
</script>

<section class="mx-auto max-w-5xl"><h1 class="text-3xl font-bold text-navy">Your cart</h1>{#if lines.length}<div class="mt-7 grid gap-6 lg:grid-cols-3"><div class="space-y-3 lg:col-span-2">{#each lines as line (line.productId + line.color)}<div class="flex gap-4 rounded-panel bg-card p-4 ring-1 ring-line"><div class="grid h-20 w-20 shrink-0 place-items-center rounded-xl bg-surface text-4xl">{line.product!.image}</div><div class="min-w-0 flex-1"><h2 class="font-semibold text-navy">{line.product!.name}</h2><p class="mt-1 text-sm text-muted">{line.color}</p><p class="mt-2 font-bold text-navy">${line.product!.price}</p></div><div class="flex flex-col items-end justify-between"><button onclick={() => update(line.productId, line.color, 0)} class="text-muted hover:text-danger" aria-label="Remove item"><Trash2 size={18}/></button><div class="flex items-center rounded-lg border border-line"><button onclick={() => update(line.productId, line.color, line.quantity - 1)} class="p-2"><Minus size={15}/></button><span class="w-7 text-center text-sm font-semibold">{line.quantity}</span><button onclick={() => update(line.productId, line.color, line.quantity + 1)} class="p-2"><Plus size={15}/></button></div></div></div>{/each}</div><aside class="h-fit rounded-panel bg-card p-5 ring-1 ring-line"><h2 class="text-lg font-bold text-navy">Order summary</h2><div class="mt-4 flex gap-2"><input bind:value={coupon} class="min-w-0 flex-1 rounded-lg border border-line px-3 py-2 text-sm" placeholder="Coupon code"/><button onclick={() => applied = coupon.toUpperCase() === 'WELCOME10'} class="rounded-lg bg-surface px-3 text-sm font-semibold text-primary">Apply</button></div>{#if applied}<p class="mt-2 text-sm text-success">WELCOME10 applied — 10% off</p>{/if}<div class="mt-5 space-y-3 text-sm"><p class="flex justify-between"><span class="text-muted">Subtotal</span><span>${subtotal.toFixed(2)}</span></p><p class="flex justify-between"><span class="text-muted">Shipping</span><span>{shipping === 0 ? 'Free' : '$' + shipping}</span></p><p class="flex justify-between"><span class="text-muted">Discount</span><span>-${discount.toFixed(2)}</span></p><p class="flex justify-between border-t border-line pt-3 text-base font-bold text-navy"><span>Total</span><span>${total.toFixed(2)}</span></p></div><button onclick={() => navigate('/checkout')} class="mt-6 w-full rounded-xl bg-primary px-4 py-3 font-semibold text-white">Proceed to checkout</button><button onclick={() => navigate('/products')} class="mt-3 w-full text-sm font-semibold text-primary">Continue shopping</button></aside></div>{:else}<div class="mt-7 rounded-panel bg-card p-12 text-center ring-1 ring-line"><p class="text-5xl">🛒</p><h2 class="mt-4 text-xl font-bold text-navy">Your cart is waiting</h2><p class="mt-2 text-muted">Discover something you’ll love and add it here.</p><button onclick={() => navigate('/products')} class="mt-6 rounded-xl bg-primary px-5 py-3 font-semibold text-white">Continue shopping</button></div>{/if}</section>
